<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import UiDialog from '@/components/ui/UiDialog.vue'
import UiButton from '@/components/ui/UiButton.vue'
import {errorText} from '@/features/models/api'
import {displayPath} from '@/lib/paths'
import {modelTransferApi,transferResultApi,type TransferResult} from './modelTransfer'
const props=defineProps<{operationId?:string|null}>()
const emit=defineEmits<{close:[];retry:[TransferResult];refresh:[TransferResult]}>()
const result=ref<TransferResult|null>(null),loading=ref(false),executing=ref(false),error=ref('');const busy=computed(()=>loading.value||executing.value);let generation=0
onBeforeUnmount(()=>{generation++})
const title=computed(()=>result.value?.kind==='export'?'导出结果':result.value?.kind==='import'?'导入结果':'同步结果')
const count=(status:string)=>result.value?.items.filter(i=>i.status===status).length??0
const needsComparison=computed(()=>['stale_baseline','file_changed','layout_changed','asset_drift','portable_manager_drift','sync_source_changed','remote_changed','remote_advanced','sync_compare','sync_plan'].includes(result.value?.errorCode??''))
const canRetry=computed(()=>result.value&&['failed','partial','running'].includes(result.value.phase)&&(result.value.phase==='running'||count('pending')>0||!!result.value.errorCode))
function failureReason(code:string|null){if(!code)return '原操作尚未完成最终核验。';if(code.includes('backup'))return '更新前备份未完成或未通过完整性核验；请核对备份与当前内容。';if(['stale_baseline','file_changed','layout_changed','asset_drift','portable_manager_drift','sync_source_changed'].includes(code))return '内容在预览后发生修改，当前内容已保留；需要重新读取比较。';if(code==='provider_auth_keychain')return '本机安全存储暂不可用，授权保护未完成；当前配置已保留，请恢复安全存储可用后核对原操作。';if(code.includes('credential')||code==='asset_secret')return '所选凭据未通过本机安全存储核验，相关内容未确认完成。';if(code.startsWith('remote')||code.includes('transport')||code==='endpoint_changed')return '连接或云端版本发生变化，结果尚未确认；请核对原操作。';if(code==='sync_compare')return '无法完整比较本次变化，更新未开始。';if(code==='portable_partial')return '部分目标资源未能完成写入或读回核验，已完成项保留。请检查文件占用和目录权限后重试。';return '文件写入或结果核验未完成。请检查目标目录权限、文件占用和当前内容后重试。'}
const statusText:Record<string,string>={pending:'未完成',completed:'已完成',unchanged:'未变化',skipped:'已跳过'}
async function read(){const current=++generation;loading.value=true;error.value='';try{const value=await transferResultApi.read(props.operationId??undefined);if(current===generation)result.value=value}catch(e){if(current===generation)error.value=errorText(e)}finally{if(current===generation)loading.value=false}}
async function retry(){if(!result.value||busy.value)return;const receipt=result.value;if(receipt.kind==='import'||receipt.kind==='download'){if(!receipt.retry){error.value='旧版记录缺少重试范围，请从原文件重新导入。';return}emit('retry',receipt);return}executing.value=true;error.value='';try{if(receipt.kind==='export')await modelTransferApi.export(receipt.id);else throw new Error('旧远端记录不可直接重传。请打开新版同步预览或按原操作标识只读核对。')}catch(e){error.value=errorText(e)}finally{executing.value=false;const message=error.value;await read();if(message)error.value=message}}
async function openDirectory(){if(!result.value)return;try{await transferResultApi.openDirectory(result.value.id)}catch(e){error.value=errorText(e)}}
watch(()=>props.operationId,read,{immediate:true})
</script>
<template><UiDialog :open="true" :title="title" wide :busy="executing" panel-class="sync-result-dialog" @close="emit('close')"><p v-if="busy" role="status">正在读取操作结果…</p><p v-if="error" class="model-error" role="alert">{{ error }}</p><p v-if="!busy&&!result&&!error" class="model-muted">尚无可查看的操作结果。</p><template v-if="result"><p class="model-muted">本次操作的处理记录</p><dl class="sx-result-facts"><dt>处理状态</dt><dd>{{ result.phase==='complete'?'已完成':result.phase==='partial'?'部分完成':result.phase==='running'?'处理中或待核对':'未完成' }}</dd><dt>所选内容</dt><dd>{{ result.items.length }} 项（含所需依赖）</dd></dl><p class="sx-result-summary">已完成 {{ count('completed') }} · 未变化 {{ count('unchanged') }} · 已跳过 {{ count('skipped') }} · 未完成 {{ count('pending') }}</p><ul class="sx-result-items"><li v-for="item in result.items" :key="item.id"><div><strong>{{ item.label }}</strong><small v-if="item.status==='pending'">{{ failureReason(result.errorCode) }}</small><small v-else-if="item.status==='skipped'">本次未选择定义来源，已跳过。</small></div><span>{{ statusText[item.status]??'待核对' }}</span></li></ul><div v-if="result.exportPath" class="sx-export-result"><span class="local-path">{{ displayPath(result.exportPath) }}</span><UiButton size="sm" variant="ghost" :disabled="busy" @click="openDirectory">打开备份包目录</UiButton></div><p v-if="result.errorCode" class="model-muted">{{ failureReason(result.errorCode) }}</p></template><template #actions><UiButton v-if="error&&!result" :disabled="busy" @click="read">重新读取</UiButton><UiButton v-if="canRetry&&!needsComparison" variant="primary" :disabled="busy" :loading="busy" @click="retry">{{ result?.phase==='running'?'核对原操作':'重试未完成项' }}</UiButton><UiButton v-if="needsComparison&&result" variant="primary" :disabled="busy" @click="emit('refresh',result)">重新比较</UiButton></template></UiDialog></template>
<style scoped>:global(dialog.ui-dialog.sync-result-dialog.wide){width:min(720px,calc(86vw / var(--ui-zoom)));max-height:calc(78vh / var(--ui-zoom))}.model-error{color:var(--red)}.model-muted,.sx-result-facts dt{color:var(--muted)}.sx-result-facts{display:grid;grid-template-columns:100px 1fr;gap:8px 16px}.sx-result-facts dd{margin:0}.sx-result-items{list-style:none;padding:0;max-height:300px;overflow:auto}.sx-result-items li{display:flex;justify-content:space-between;gap:16px;padding:10px 0;border-bottom:1px solid var(--border)}.sx-result-items small{display:block;color:var(--muted);font-size:var(--text-caption);line-height:1.6;margin-top:4px}.sx-result-items strong{font-weight:var(--weight-medium)}.sx-export-result{display:grid;gap:8px;overflow-wrap:anywhere}.sx-export-result button{justify-self:start}</style>
